program.compute:
opts=read('/input/options')
ids=[]
for i in range(len(opts)):
  for j in range(i+1,len(opts)):
    for k in range(j+1,len(opts)):
      c=[opts[i]['id'],opts[j]['id'],opts[k]['id']]
      if valid(c):
        ids=c
        break
    if ids!=[]:
      break
  if ids!=[]:
    break
if ids==[]:
  for i in range(len(opts)):
    for j in range(i+1,len(opts)):
      c=[opts[i]['id'],opts[j]['id']]
      if valid(c):
        ids=c
        break
    if ids!=[]:
      break
result=ids

program.effects:
if result!=[]:
  write('/output/selection',result)
  send('team',result)
  if exists('/tmp/cache'):
    delete('/tmp/cache')

